// ServerInterface represents all server handlers.
type ServerInterface interface {
	// VerifyMfa Pass two-step verification
	// (POST /api/console/v1/auth/mfa)
	VerifyMfa(w http.ResponseWriter, r *http.Request)
	// RequestPasswordReset Request a password reset email
	// (POST /api/console/v1/auth/password-reset)
	RequestPasswordReset(w http.ResponseWriter, r *http.Request)
	// ResetPassword Reset a forgotten password
	// (POST /api/console/v1/auth/password-reset/complete)
	ResetPassword(w http.ResponseWriter, r *http.Request)
	// RegenerateRecoveryCodes Make new recovery codes
	// (POST /api/console/v1/auth/recovery-codes)
	RegenerateRecoveryCodes(w http.ResponseWriter, r *http.Request)
	// Register Register with an invite code
	// (POST /api/console/v1/auth/register)
	Register(w http.ResponseWriter, r *http.Request)
	// SignIn Sign in with email and password
	// (POST /api/console/v1/auth/sign-in)
	SignIn(w http.ResponseWriter, r *http.Request)
	// SignOut End the session
	// (POST /api/console/v1/auth/sign-out)
	SignOut(w http.ResponseWriter, r *http.Request)
	// ConfirmTotpSetup Finish enabling two-step verification
	// (POST /api/console/v1/auth/totp/confirm)
	ConfirmTotpSetup(w http.ResponseWriter, r *http.Request)
	// BeginTotpSetup Start enabling two-step verification
	// (POST /api/console/v1/auth/totp/setup)
	BeginTotpSetup(w http.ResponseWriter, r *http.Request)
	// GetBalance The account's balance
	// (GET /api/console/v1/balance)
	GetBalance(w http.ResponseWriter, r *http.Request)
	// ListCalls The account's calls
	// (GET /api/console/v1/calls)
	ListCalls(w http.ResponseWriter, r *http.Request, params ListCallsParams)
	// AggregateCalls Calls and user charges grouped by UTC day, model or key
	// (GET /api/console/v1/calls/aggregate)
	AggregateCalls(w http.ResponseWriter, r *http.Request, params AggregateCallsParams)
	// ExportCalls Stream the account's call metadata as CSV
	// (GET /api/console/v1/calls/export)
	ExportCalls(w http.ResponseWriter, r *http.Request, params ExportCallsParams)
	// GetCall One call
	// (GET /api/console/v1/calls/{call_id})
	GetCall(w http.ResponseWriter, r *http.Request, callId CallId)
	// ListKeys The account's API keys
	// (GET /api/console/v1/keys)
	ListKeys(w http.ResponseWriter, r *http.Request, params ListKeysParams)
	// CreateKey Make an API key
	// (POST /api/console/v1/keys)
	CreateKey(w http.ResponseWriter, r *http.Request)
	// DeleteKey Delete an API key
	// (DELETE /api/console/v1/keys/{key_id})
	DeleteKey(w http.ResponseWriter, r *http.Request, keyId KeyId)
	// GetKey One API key
	// (GET /api/console/v1/keys/{key_id})
	GetKey(w http.ResponseWriter, r *http.Request, keyId KeyId)
	// UpdateKey Change an API key's settings
	// (PUT /api/console/v1/keys/{key_id})
	UpdateKey(w http.ResponseWriter, r *http.Request, keyId KeyId)
	// CreateOrder Place a top-up order
	// (POST /api/console/v1/orders)
	CreateOrder(w http.ResponseWriter, r *http.Request, params CreateOrderParams)
	// GetOrder One top-up order
	// (GET /api/console/v1/orders/{order_id})
	GetOrder(w http.ResponseWriter, r *http.Request, orderId OrderId)
	// CancelOrder Cancel an order that waits for payment
	// (POST /api/console/v1/orders/{order_id}/cancel)
	CancelOrder(w http.ResponseWriter, r *http.Request, orderId OrderId)
	// VerifyOrder Ask the payment channel about an order now
	// (POST /api/console/v1/orders/{order_id}/verify)
	VerifyOrder(w http.ResponseWriter, r *http.Request, orderId OrderId)
	// ChangePassword Change the signed-in user's password
	// (POST /api/console/v1/password)
	ChangePassword(w http.ResponseWriter, r *http.Request)
	// ListPaymentMethods What some credits cost through each payment method
	// (GET /api/console/v1/payment-methods)
	ListPaymentMethods(w http.ResponseWriter, r *http.Request, params ListPaymentMethodsParams)
	// GetSession The current session
	// (GET /api/console/v1/session)
	GetSession(w http.ResponseWriter, r *http.Request)
	// GetSite The site the request's domain belongs to
	// (GET /api/console/v1/site)
	GetSite(w http.ResponseWriter, r *http.Request)
	// ListStatement The account's credit statement
	// (GET /api/console/v1/statement)
	ListStatement(w http.ResponseWriter, r *http.Request, params ListStatementParams)
	// ExportStatement The account's credit statement as a CSV file
	// (GET /api/console/v1/statement.csv)
	ExportStatement(w http.ResponseWriter, r *http.Request)
	// GetVersion The version of the running program
	// (GET /api/console/v1/version)
	GetVersion(w http.ResponseWriter, r *http.Request)
}

